const fs = require('node:fs');
async function handle(file, jobs) {
  const body = fs.readFileSync(file, 'utf8');
  await Promise.all(jobs.map(job => remoteWrite(job)));
  return body;
}

type Input = { count: number; name: string };
export function parse(raw: string): string {
  const input = JSON.parse(raw) as Input;
  const count = input.count || 10;
  return input.name.toUpperCase() + ':' + count;
}

query = signal('');
rows = signal<Row[]>([]);
constructor() {
  effect(() => {
    this.api.search(this.query()).subscribe(rows => this.rows.set(rows));
  });
}

function Search({ query, rows }) {
  const [data, setData] = useState([]);
  rows.sort((a, b) => a.name.localeCompare(b.name));
  useEffect(() => {
    fetch('/search?q=' + encodeURIComponent(query)).then(r => r.json()).then(setData);
  }, []);
  return <List rows={data} />;
}

